from decimal import Decimal

from .money import round_money, to_decimal

# Units of each currency per 1 EUR (updated monthly by finance).
RATES = {
    "EUR": Decimal("1"),
    "USD": Decimal("1.0850"),
    "GBP": Decimal("0.8550"),
    "CHF": Decimal("0.9420"),
}


def rate(currency):
